//! Embedded admin web UI: Askama-templated HTML + htmx for interactivity, styled with
//! Tailwind CSS. No CDN, no runtime Node/npm/network dependency — the compiled Tailwind CSS
//! (`assets/tailwind.css`, generated by the standalone `tailwindcss` binary from
//! `assets/input.css`) and htmx (`assets/htmx.min.js`, vendored) are both baked into the
//! binary via `include_str!` and inlined directly into the single `GET /` response. Served at
//! `GET /` (full page) and `GET /ui/*` (htmx fragment endpoints) by `src/api.rs`.
//!
//! To regenerate the CSS after changing template classes: run the standalone `tailwindcss`
//! binary (<https://github.com/tailwindlabs/tailwindcss/releases>) —
//! `tailwindcss -i assets/input.css -o assets/tailwind.css --minify` — then rebuild.
use crate::manager::{CountryInfo, ServerSummary, TunnelInfo};
use askama::Template;

const TAILWIND_CSS: &str = include_str!("../assets/tailwind.css");
const HTMX_JS: &str = include_str!("../assets/htmx.min.js");

#[derive(Template)]
#[template(path = "index.html")]
pub struct IndexTemplate {
    pub tailwind_css: &'static str,
    pub htmx_js: &'static str,
    pub login_error: Option<String>,
    pub locations: Vec<CountryInfo>,
    pub tunnels: Vec<TunnelInfo>,
}

impl IndexTemplate {
    pub fn new(
        login_error: Option<String>,
        locations: Vec<CountryInfo>,
        tunnels: Vec<TunnelInfo>,
    ) -> Self {
        Self {
            tailwind_css: TAILWIND_CSS,
            htmx_js: HTMX_JS,
            login_error,
            locations,
            tunnels,
        }
    }
}

#[derive(Template)]
#[template(path = "locations.html")]
pub struct LocationsTemplate {
    pub locations: Vec<CountryInfo>,
}

#[derive(Template)]
#[template(path = "tunnels.html")]
pub struct TunnelsTemplate {
    pub tunnels: Vec<TunnelInfo>,
}

#[derive(Template)]
#[template(path = "servers.html")]
pub struct ServersTemplate {
    pub location: String,
    pub servers: Vec<ServerSummary>,
}
